/**
 * Levenshtein distance calculation
 * Returns the minimum number of single-character edits
 * (insertions, deletions, or substitutions) required to change
 * one word into another.
 */
function levenshteinDistance(str1, str2) {
  const m = str1.length;
  const n = str2.length;

  // Create a matrix to store distances
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  // Initialize base cases
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill in the rest of the matrix
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (str1[i - 1] === str2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + Math.min(
          dp[i - 1][j],    // deletion
          dp[i][j - 1],    // insertion
          dp[i - 1][j - 1] // substitution
        );
      }
    }
  }

  return dp[m][n];
}

/**
 * Creates a debug helper for KnockoutJS binding errors.
 *
 * @param {Object} viewModel - A plain JavaScript object with properties
 * @returns {Object} A debug helper object
 */
function createDebugHelper(viewModel) {
  const viewModelProps = Object.keys(viewModel || {});

  return {
    /**
     * Diagnoses a missing property binding error.
     *
     * @param {string} propertyName - The name of the property that failed to bind
     * @returns {Object} An object with error details
     */
    diagnoseMissingProperty(propertyName) {
      const availableProperties = [...viewModelProps].sort();

      // Find the closest matching property
      let suggestion = null;
      let minDistance = Infinity;

      for (const prop of availableProperties) {
        const distance = levenshteinDistance(propertyName, prop);

        if (distance <= 3 && distance < minDistance) {
          minDistance = distance;
          suggestion = prop;
        }
      }

      // If tie, we already process alphabetically since availableProperties is sorted
      // so the first one found will be alphabetically first among ties

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: suggestion
      };
    }
  };
}

module.exports = {
  createDebugHelper,
  // Also export levenshteinDistance for testing purposes
  levenshteinDistance
};
EOF"}

{"command": "cat > /app/task_file/output/test-ko-debug.js << 'EOF'
const { createDebugHelper } = require('./ko-debug');

// Define a sample ViewModel with at least these properties:
// items, selectedItem, filterText, isLoading, totalCount
const sampleViewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 0
};

const debugHelper = createDebugHelper(sampleViewModel);

let passed = 0;
let failed = 0;

function assertEqual(actual, expected, description) {
  if (JSON.stringify(actual) === JSON.stringify(expected)) {
    console.log(`PASS: ${description}`);
    passed++;
  } else {
    console.log(`FAIL: ${description}`);
    console.log(`  Expected: ${JSON.stringify(expected)}`);
    console.log(`  Actual:   ${JSON.stringify(actual)}`);
    failed++;
  }
}

// Test 1: Diagnose missing property "item" should suggest "items"
console.log('\n--- Test 1: Missing property "item" ---');
let result1 = debugHelper.diagnoseMissingProperty('item');
assertEqual(result1.error, true, 'error is true');
assertEqual(result1.missingProperty, 'item', 'missingProperty is "item"');
assertEqual(result1.availableProperties.length > 0, true, 'has available properties');
assertEqual(result1.availableProperties[0], 'filterText', 'availableProperties is sorted (first: filterText)');
assertEqual(result1.suggestion, 'items', 'suggestion is "items"');

// Test 2: Diagnose missing property "selctedItem" should suggest "selectedItem"
console.log('\n--- Test 2: Missing property "selctedItem" ---');
let result2 = debugHelper.diagnoseMissingProperty('selctedItem');
assertEqual(result2.error, true, 'error is true');
assertEqual(result2.missingProperty, 'selctedItem', 'missingProperty is "selctedItem"');
assertEqual(result2.suggestion, 'selectedItem', 'suggestion is "selectedItem"');

// Test 3: Diagnose missing property "completelyWrong" should have null suggestion
console.log('\n--- Test 3: Missing property "completelyWrong" ---');
let result3 = debugHelper.diagnoseMissingProperty('completelyWrong');
assertEqual(result3.error, true, 'error is true');
assertEqual(result3.missingProperty, 'completelyWrong', 'missingProperty is "completelyWrong"');
assertEqual(result3.suggestion, null, 'suggestion is null (no close match)');

// Test 4: Diagnose missing property "isLoad" should suggest "isLoading"
console.log('\n--- Test 4: Missing property "isLoad" ---');
let result4 = debugHelper.diagnoseMissingProperty('isLoad');
assertEqual(result4.error, true, 'error is true');
assertEqual(result4.missingProperty, 'isLoad', 'missingProperty is "isLoad"');
assertEqual(result4.suggestion, 'isLoading', 'suggestion is "isLoading"');

// Summary
console.log(`\n--- Results: ${passed} passed, ${failed} failed ---`);

if (failed > 0) {
  process.exit(1);
}
EOF"}
